from collections import Counter
import math

class Solution:
    def minOperations(self, nums: list[int]) -> int:
        count = Counter(nums)
        ops = 0
        for freq in count.values():
            if freq == 1:
                return -1
            ops += math.ceil(freq / 3)
        return ops

